<script setup lang="ts">import{ref}from'vue';import type{TriggerControl}from'../../types/protocol';defineProps<{control:TriggerControl}>();const emit=defineEmits<{fire:[]}>();const pressed=ref(false);function key(e:KeyboardEvent){if(!e.repeat&&(e.key==='Enter'||e.key===' ')){e.preventDefault();emit('fire')}}</script><template><button class="trigger" :disabled="control.read_only" :class="{pressed}" @pointerdown="pressed=true;$emit('fire')" @pointerup="pressed=false" @pointercancel="pressed=false" @keydown="key">{{control.label}}</button></template>
